import { Sheet } from '@/components/ui/Sheet.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import type { Kind } from '@lexpad/core';
import type { Order } from './filters.js';
import styles from './ViewSheet.module.css';

interface ViewSheetProps {
  order: Order;
  onOrder: (order: Order) => void;
  levels: readonly string[];
  level: string | undefined;
  onLevel: (level: string | undefined) => void;
  kinds: readonly Kind[];
  kind: Kind | undefined;
  onKind: (kind: Kind | undefined) => void;
  onClose: () => void;
}

const ORDERS: readonly {
  order: Order;
  labelKey: 'notebook.orderLatest' | 'notebook.orderPages' | 'notebook.orderAlpha';
}[] = [
  { order: 'recent', labelKey: 'notebook.orderLatest' },
  { order: 'position', labelKey: 'notebook.orderPages' },
  { order: 'alpha', labelKey: 'notebook.orderAlpha' },
];

/**
 * How the notebook is ordered and narrowed, in one sheet. What each row
 * shows (meanings, examples) is not in here: those are switches on the
 * screen itself, since they are not filters (2026-10-02).
 *
 * These controls used to sit above the list: three rows of them, before a
 * single word. They are each worth having and none of them is worth a
 * third of the screen every time somebody opens their notebook, so the two
 * filters people actually reach for stay outside and the rest live here.
 */
export function ViewSheet({
  order,
  onOrder,
  levels,
  level,
  onLevel,
  kinds,
  kind,
  onKind,
  onClose,
}: ViewSheetProps): React.JSX.Element {
  return (
    <Sheet title={t('notebook.viewTitle')} onClose={onClose}>
      <div className={styles.group}>
        <h3 className={styles.label}>{t('notebook.order')}</h3>
        <div className={styles.row}>
          {ORDERS.map((entry) => (
            <button
              key={entry.order}
              type="button"
              className={cx(styles.chip, order === entry.order && styles.chipOn)}
              aria-pressed={order === entry.order}
              onClick={() => {
                onOrder(entry.order);
              }}
            >
              {t(entry.labelKey)}
            </button>
          ))}
        </div>
      </div>

      {levels.length > 0 && (
        <div className={styles.group}>
          <h3 className={styles.label}>{t('notebook.byLevel')}</h3>
          <div className={styles.row}>
            {levels.map((entry) => (
              <button
                key={entry}
                type="button"
                className={cx(styles.chip, level === entry && styles.chipOn)}
                aria-pressed={level === entry}
                onClick={() => {
                  onLevel(level === entry ? undefined : entry);
                }}
              >
                {entry}
              </button>
            ))}
          </div>
        </div>
      )}

      {kinds.length > 0 && (
        <div className={styles.group}>
          <h3 className={styles.label}>{t('notebook.byKind')}</h3>
          <div className={styles.row}>
            {kinds.map((entry) => (
              <button
                key={entry}
                type="button"
                className={cx(styles.chip, kind === entry && styles.chipOn)}
                aria-pressed={kind === entry}
                onClick={() => {
                  onKind(kind === entry ? undefined : entry);
                }}
              >
                {t(`kind.${entry}`)}
              </button>
            ))}
          </div>
        </div>
      )}
    </Sheet>
  );
}
