import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import {
  NavigationType,
  useLocation,
  useMatch,
  useNavigate,
  useNavigationType,
  useSearchParams,
} from 'react-router-dom';
import { KINDS, type Kind } from '@lexpad/core';
import { FILTERS, type Filter, type Order } from './filters.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { isoDayLabel, localTimeZone } from '@/lib/format.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { useDebounced } from '@/lib/useDebounced.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { gradeCard, setProgressFlags } from '@/db/mutations.js';
import { syncSoon } from '@/sync/store.js';
import { Button } from '@/components/ui/Button.js';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { usePane } from '@/components/layout/pane.js';
import { AddSheet } from './AddSheet.js';
import { ViewSheet } from './ViewSheet.js';
import { PasteSheet } from './PasteSheet.js';
import { NotebookChip } from './NotebookChip.js';
import { DEFAULT_VIEW, loadView, rememberedView, saveView } from './viewMemory.js';
import {
  placeKey,
  placeToRestore,
  rememberPlace,
  returnsToPlace,
  type NotebookPlace,
} from './placeMemory.js';
import { useHeaderFold } from './useHeaderFold.js';
import { WordRow } from './WordRow.js';
import { EMPTY_NOTEBOOK, loadNotebook, type NotebookView } from './data.js';
import styles from './Notebook.module.css';

/** Entries shown before the notebook offers to turn the page. */
const PAGE_SIZE = 40;

/**
 * How long typing in the search box must pause before the list is searched.
 * Every search rebuilds the notebook's live query over every word; once per
 * keystroke made fast typing lag on a large notebook. Short enough to read as
 * instant. A feel of this screen, not data.
 */
const SEARCH_DEBOUNCE_MS = 150;

/** How many ids "Practise these" hands to the session; the session caps itself anyway. */
const PRACTISE_MAX = 300;

/**
 * The notebook: a ruled page of every word, with search, filters, ordering
 * and a density switch. "Hide meanings" turns it into a self-test, where
 * revealing a row offers the two grades.
 */
export function Notebook(): React.JSX.Element {
  const navigate = useNavigate();
  const [params, setParams] = useSearchParams();
  const location = useLocation();
  const navigationType = useNavigationType();

  // Coming back from a word: where the reader was, read once as the screen
  // arrives; see placeMemory.ts. Undefined on a fresh visit.
  const [returning] = useState(() =>
    placeToRestore(location.key, navigationType === NavigationType.Pop, returnsToPlace(location.state)),
  );

  // The view this device last used, held in memory so a return from another
  // tab draws it on the first frame; see viewMemory.ts.
  const start = rememberedView() ?? DEFAULT_VIEW;
  const [filter, setFilter] = useState<Filter>(start.filter);
  const [order, setOrder] = useState<Order>(start.order);
  const [query, setQuery] = useState(returning?.query ?? '');
  const [showExamples, setShowExamples] = useState(start.showExamples);
  const [showMeanings, setShowMeanings] = useState(start.showMeanings);
  const compact = !showExamples;
  const hideMeanings = !showMeanings;
  const [revealed, setRevealed] = useState<ReadonlySet<string>>(() => new Set(returning?.revealed));
  // The header gets out of the way of a long list; see useHeaderFold.ts.
  const headerRef = useRef<HTMLDivElement>(null);
  const toolsRef = useRef<HTMLDivElement>(null);
  const { fold, offset, reveal: revealHeader, settle } = useHeaderFold(headerRef, toolsRef);
  const listRef = useRef<HTMLDivElement>(null);
  /*
   * The add sheet is open when the URL says so, rather than held in state
   * that is read once at mount. The button that opens it lives in the tab
   * bar now and navigates here with ?add=1 -- and from the notebook that is
   * not a new screen, so nothing remounts and a copy kept in state would
   * never have heard about it. Back closes the sheet too, which it should.
   */
  const addOpen = params.get('add') === '1';
  const setAddOpen = (open: boolean): void => {
    const next = new URLSearchParams(params);
    if (open) next.set('add', '1');
    else next.delete('add');
    setParams(next, { replace: true });
  };
  const [pasteOpen, setPasteOpen] = useState(false);
  const [viewOpen, setViewOpen] = useState(false);
  // Which page (day) the Pages order is showing; undefined means all of them.
  const [activePage, setActivePage] = useState<string | undefined>(returning?.activePage);
  // The prototype shows 40 entries and offers to turn the page for more.
  const [limit, setLimit] = useState(returning?.limit ?? PAGE_SIZE);

  const topic = params.get('topic') ?? undefined;
  const level = params.get('level') ?? undefined;
  const kindParam = params.get('kind');
  const kind =
    kindParam !== null && (KINDS as readonly string[]).includes(kindParam) ? (kindParam as Kind) : undefined;
  // Whether the sheet is holding something back, so its button can say
  // so rather than looking identical whatever is set behind it.
  const viewNarrowed = level !== undefined || kind !== undefined;

  // The box follows every key; the list follows the settled text.
  const searched = useDebounced(query, SEARCH_DEBOUNCE_MS);
  const view: NotebookView = useMemo(
    () => ({ filter, order, query: searched, topic, level, kind }),
    [filter, order, searched, topic, level, kind],
  );
  const data = useLiveQuery(() => loadNotebook(view), EMPTY_NOTEBOOK, [view]);
  const timeZone = useMemo(() => localTimeZone(), []);

  const reveal = useCallback((wordId: string): void => {
    setRevealed((previous) => new Set(previous).add(wordId));
  }, []);

  const star = useCallback(
    (wordId: string, starred: boolean): void => {
      void setProgressFlags(wordId, { starred }, timeZone).then(() => syncSoon());
    },
    [timeZone],
  );

  const selfGrade = useCallback(
    (wordId: string, correct: boolean): void => {
      void gradeCard({ wordId, correct, cardType: 'classic' }, timeZone).then(() => syncSoon());
      setRevealed((previous) => {
        const next = new Set(previous);
        next.delete(wordId);
        return next;
      });
    },
    [timeZone],
  );

  const clearNarrowing = (): void => {
    const next = new URLSearchParams(params);
    next.delete('topic');
    next.delete('level');
    next.delete('kind');
    setParams(next, { replace: true });
  };

  /*
   * The first visit of a session reads the stored view; later visits already
   * have it in memory. A level or kind comes back through the address, where
   * it lives, unless the address arrived with a narrowing of its own -- a link
   * from Today that asks for one topic means that topic.
   */
  const restored = useRef(rememberedView() !== undefined);
  useEffect(() => {
    let live = true;
    void loadView().then((view) => {
      if (!live) return;
      if (!restored.current) {
        setFilter(view.filter);
        setOrder(view.order);
        setShowExamples(view.showExamples);
        setShowMeanings(view.showMeanings);
        restored.current = true;
      }
      const arrivedNarrowed = params.has('topic') || params.has('level') || params.has('kind');
      if (!arrivedNarrowed && (view.level !== undefined || view.kind !== undefined)) {
        const next = new URLSearchParams(params);
        if (view.level !== undefined) next.set('level', view.level);
        if (view.kind !== undefined) next.set('kind', view.kind);
        setParams(next, { replace: true });
      }
    });
    return () => {
      live = false;
    };
    // Once per visit: the address is read as it arrived.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => {
    if (!restored.current) return;
    saveView({
      filter,
      order,
      showMeanings,
      showExamples,
      ...(level === undefined ? {} : { level }),
      ...(kind === undefined ? {} : { kind }),
    });
  }, [filter, order, showMeanings, showExamples, level, kind]);

  /*
   * Back from a word: once the rows are on the page, put the reader where
   * they were. The search and the turned pages were restored with the
   * screen's first state, so the first rows to arrive are the ones that
   * were showing. The row that was at the top of the window goes back to
   * the same height, which still holds if a word above it was moved or
   * removed meanwhile; without it, the scroll position does.
   */
  const pendingPlace = useRef(returning);
  useLayoutEffect(() => {
    const place = pendingPlace.current;
    if (place === undefined || data === EMPTY_NOTEBOOK) return;
    pendingPlace.current = undefined;
    if (placeKey(data.notebook?.id, data.across) !== place.key) {
      // Another notebook is showing now: that place means nothing here.
      setQuery('');
      setLimit(PAGE_SIZE);
      setActivePage(undefined);
      setRevealed(new Set());
      return;
    }
    const anchor = place.anchor;
    const row =
      anchor === undefined
        ? undefined
        : [...(listRef.current?.querySelectorAll<HTMLElement>('[data-word-id]') ?? [])].find(
            (element) => element.dataset.wordId === anchor.wordId,
          );
    const top =
      row === undefined || anchor === undefined
        ? place.scrollY
        : window.scrollY + row.getBoundingClientRect().top - anchor.top;
    window.scrollTo({ top: Math.max(0, top), behavior: 'instant' });
    settle(window.scrollY > 0 ? place.fold : 'full');
  }, [data, settle]);

  /*
   * Leaving: keep the place for a return. Taken as the screen unmounts,
   * while its rows are still laid out where the reader left them. The
   * values it needs are copied after every render rather than read from a
   * stale closure.
   */
  const leaving = useRef<
    (Omit<NotebookPlace, 'scrollY' | 'anchor'> & { key: string | undefined }) | undefined
  >(undefined);
  useLayoutEffect(() => {
    leaving.current = {
      key: placeKey(data.notebook?.id, data.across),
      entry: location.key,
      query,
      limit,
      activePage,
      revealed: [...revealed],
      fold,
    };
  });
  useLayoutEffect(() => {
    const list = listRef.current;
    return () => {
      if (leaving.current === undefined) return;
      const { key, ...place } = leaving.current;
      if (key === undefined) return;
      // The first row whose top is on screen, and where it sat.
      let anchor: NotebookPlace['anchor'];
      for (const element of list?.querySelectorAll<HTMLElement>('[data-word-id]') ?? []) {
        const top = element.getBoundingClientRect().top;
        const wordId = element.dataset.wordId;
        if (top >= 0 && wordId !== undefined) {
          anchor = { wordId, top };
          break;
        }
      }
      rememberPlace(key, { ...place, scrollY: window.scrollY, anchor });
    };
  }, []);

  /** Sets or clears one narrowing in the URL, so it survives a back and a share. */
  const narrow = (key: 'topic' | 'level' | 'kind', value: string | undefined): void => {
    const next = new URLSearchParams(params);
    if (value === undefined) next.delete(key);
    else next.set(key, value);
    setParams(next, { replace: true });
  };

  /*
   * What is narrowing the list right now, one removable chip each. It used
   * to be a dot-joined tail on the count line -- "8 entries · English →
   * Spanish · General · B2 · Noun" -- which read as one long caption and
   * offered no way to take any single one of them off.
   */
  const narrowings: { key: 'topic' | 'level' | 'kind'; label: string }[] = [
    ...(topic === undefined ? [] : [{ key: 'topic' as const, label: topic }]),
    ...(level === undefined ? [] : [{ key: 'level' as const, label: level }]),
    ...(kind === undefined ? [] : [{ key: 'kind' as const, label: t(`kind.${kind}`) }]),
  ];

  const notebook = data.notebook;
  // A chosen page narrows the list to the day it names.
  const visible =
    order === 'position' && activePage !== undefined
      ? (data.pages.find((page) => page.day === activePage)?.words ?? [])
      : data.words;
  const targetLang = notebook?.targetLang ?? 'en';
  const meaningLang = notebook?.meaningLang ?? 'fa';
  const searchLabel =
    targetLang === meaningLang
      ? t('notebook.searchOne', { language: LANGUAGE_NAMES[targetLang] })
      : t('notebook.search', { target: LANGUAGE_NAMES[targetLang], meaning: LANGUAGE_NAMES[meaningLang] });
  // Anything that cuts the notebook down can be practised as it stands.
  const narrowed =
    filter !== 'all' ||
    searched.trim() !== '' ||
    topic !== undefined ||
    level !== undefined ||
    kind !== undefined;
  // Page tabs belong to the Pages order alone, and only while nothing else
  // is narrowing the list, as the prototype has it.
  const showPages =
    order === 'position' && filter === 'all' && searched.trim() === '' && data.pages.length > 0;

  // Beside the word it opened, on an expanded window: the split view owns
  // the page's <main>, and the open word is marked in the list.
  const pane = usePane();
  const Root = pane === undefined ? 'main' : 'div';
  const openWord = useMatch('/words/:wordId')?.params.wordId;

  return (
    <Root className={cx(styles.screen, pane !== undefined && styles.inPane)}>
      <div
        ref={headerRef}
        className={styles.header}
        data-fold={fold}
        style={{ '--fold': `${offset}px` } as React.CSSProperties}
        onFocus={revealHeader}
      >
        <div className={styles.titleRow}>
          <div className={styles.titleBlock}>
            <h1 className={styles.title}>{t('notebook.title')}</h1>
            <span className={styles.count}>
              {data.words.length === 1
                ? t('notebook.countOne')
                : t('notebook.count', { count: data.words.length })}
              {/* The pair, so the search placeholder is not the only place
                  that says which two languages this notebook is between. */}
              {` \u00b7 ${LANGUAGE_NAMES[targetLang]} \u2192 ${LANGUAGE_NAMES[meaningLang]}`}
            </span>
          </div>
          {/* Sorting and the level and kind facets; outside the
              sheet they cost three rows before the first word. Labelled
              rather than a bare icon, which people read as the facets
              having been taken away. It sits up here beside the title so
              the filter chips get the whole of their own row: sharing it
              left the last chip half under the button. */}
          <button
            type="button"
            className={cx(styles.viewButton, viewNarrowed && styles.viewButtonOn)}
            onClick={() => {
              setViewOpen(true);
            }}
          >
            <Icon name="settings" size={17} weight={1.9} />
            <span>{t('notebook.filter')}</span>
            {viewNarrowed && <span className={styles.viewDot} aria-hidden="true" />}
          </button>
          {/* In the list pane the paste button sits up here beside Filter.
              Floating at the foot of a pane this narrow it covered the
              star and speaker of whichever entry scrolled under it, and a
              window this size has the room to keep it out of the way. */}
          {notebook && pane !== undefined && (
            <button
              type="button"
              className={styles.pasteButton}
              aria-label={t('notebook.paste')}
              title={t('notebook.paste')}
              onClick={() => {
                setPasteOpen(true);
              }}
            >
              <Icon name="note" size={18} weight={1.9} />
            </button>
          )}
        </div>

        {/* Which notebook is in view. It used to sit inside the count line,
            a button in the middle of a sentence. */}
        <NotebookChip className={styles.notebookChip} />

        <div ref={toolsRef} className={styles.searchWrap}>
          <Icon name="search" size={18} weight={1.9} className={styles.searchIcon} />
          <input
            className={styles.search}
            type="search"
            value={query}
            dir="auto"
            placeholder={searchLabel}
            aria-label={searchLabel}
            autoComplete="off"
            autoCapitalize="none"
            autoCorrect="off"
            spellCheck={false}
            onChange={(event) => {
              setQuery(event.target.value);
            }}
          />
        </div>

        <div className={styles.filterRow}>
          <div className={styles.chips} role="group" aria-label={t('filter.all')}>
            {FILTERS.map((entry) => (
              <button
                key={entry}
                type="button"
                className={cx(styles.chip, filter === entry && styles.chipOn)}
                aria-pressed={filter === entry}
                onClick={() => {
                  setFilter(entry);
                }}
              >
                {t(`filter.${entry}`)}
              </button>
            ))}
            <span className={styles.chipsTail} aria-hidden="true" />
          </div>
        </div>

        {/* What each row shows, apart from which rows are shown. These two
            used to sit in the Filter sheet, and testers rightly said they
            are not filters (2026-10-02). Lit means shown; switching the
            meanings off is the self-test. */}
        <div className={styles.displayRow} role="group" aria-label={t('notebook.show')}>
          <span className={styles.displayLabel} aria-hidden="true">
            {t('notebook.show')}
          </span>
          <button
            type="button"
            className={cx(styles.showSwitch, showMeanings && styles.showSwitchOn)}
            aria-pressed={showMeanings}
            onClick={() => {
              setShowMeanings(!showMeanings);
              setRevealed(new Set());
            }}
          >
            <Icon name={showMeanings ? 'eye' : 'eyeOff'} size={15} weight={1.9} />
            {t('notebook.meanings')}
          </button>
          <button
            type="button"
            className={cx(styles.showSwitch, showExamples && styles.showSwitchOn)}
            aria-pressed={showExamples}
            onClick={() => {
              setShowExamples(!showExamples);
            }}
          >
            <Icon name="list" size={15} weight={1.9} />
            {t('notebook.examples')}
          </button>
        </div>

        {narrowings.length > 0 && (
          <div className={styles.narrowings}>
            {narrowings.map((one) => (
              <button
                key={one.key}
                type="button"
                className={styles.narrowing}
                aria-label={t('notebook.clearOne', { label: one.label })}
                onClick={() => {
                  narrow(one.key, undefined);
                }}
              >
                <span>{one.label}</span>
                <Icon name="close" size={13} weight={2.4} />
              </button>
            ))}
            {narrowings.length > 1 && (
              <button type="button" className={styles.clearAll} onClick={clearNarrowing}>
                {t('notebook.clearAll')}
              </button>
            )}
          </div>
        )}

        {narrowed && visible.length > 0 && (
          <button
            type="button"
            className={styles.practise}
            onClick={() => {
              // A session over exactly what is on the page: the group deck
              // takes the ids, in notebook order, and caps itself.
              const ids = visible.slice(0, PRACTISE_MAX).map((word) => word.id);
              void navigate(`/session?deck=group&ids=${ids.join(',')}`);
            }}
          >
            <Icon name="arrowRight" size={16} weight={2} />
            {visible.length === 1
              ? t('notebook.practiseOne')
              : t('notebook.practiseThese', { count: visible.length })}
          </button>
        )}

        {showPages && (
          <div className={styles.pages} role="group" aria-label={t('notebook.orderPages')}>
            <button
              type="button"
              className={cx(styles.page, activePage === undefined && styles.pageOn)}
              aria-pressed={activePage === undefined}
              onClick={() => {
                setActivePage(undefined);
              }}
            >
              {t('notebook.allPages')}
            </button>
            {data.pages.map((page) => (
              <button
                key={page.day}
                type="button"
                className={cx(styles.page, page.day === activePage && styles.pageOn)}
                aria-pressed={page.day === activePage}
                onClick={() => {
                  setActivePage(page.day === activePage ? undefined : page.day);
                }}
              >
                {isoDayLabel(page.day, data.todayIso)}
              </button>
            ))}
          </div>
        )}
      </div>

      <div ref={listRef} className={styles.list}>
        {visible.length > 0 && <span className={styles.margin} aria-hidden="true" />}
        {visible.length === 0 ? (
          /*
           * Two different nothings. A notebook with no words in it was
           * being told "nothing matches this filter, clear it to see the
           * whole notebook again" -- advice that cannot help, about a
           * filter that is not the problem.
           */
          data.total === 0 ? (
            <EmptyState
              icon="notebook"
              title={t('notebook.starterTitle')}
              body={t('notebook.starterBody')}
              actions={
                <>
                  <Button
                    onClick={() => {
                      setAddOpen(true);
                    }}
                  >
                    {t('add.title')}
                  </Button>
                  <Button
                    variant="secondary"
                    onClick={() => {
                      setPasteOpen(true);
                    }}
                  >
                    {t('notebook.paste')}
                  </Button>
                </>
              }
            />
          ) : (
            <EmptyState
              icon="search"
              tone="quiet"
              title={t('notebook.noMatchTitle')}
              body={t('notebook.empty')}
              actions={
                <Button variant="secondary" onClick={clearNarrowing}>
                  {t('notebook.clearFilters')}
                </Button>
              }
            />
          )
        ) : (
          visible.slice(0, limit).map((word) => {
            // With every notebook in view a row takes its direction, its
            // font and its voice from the notebook the word is in, not from
            // the one the page is anchored to.
            const its = data.byNotebook[word.notebookId];
            return (
              <WordRow
                key={word.id}
                word={word}
                targetLang={its?.targetLang ?? targetLang}
                meaningLang={its?.meaningLang ?? meaningLang}
                {...(data.across && its !== undefined ? { from: its.title } : {})}
                selected={word.id === openWord}
                hideMeaning={hideMeanings}
                revealed={revealed.has(word.id)}
                compact={compact}
                today={data.today}
                timeZone={timeZone}
                onOpen={() => {
                  void navigate(`/words/${word.id}`);
                }}
                onReveal={() => {
                  reveal(word.id);
                }}
                onStar={(starred) => {
                  star(word.id, starred);
                }}
                onGrade={(correct) => {
                  selfGrade(word.id, correct);
                }}
              />
            );
          })
        )}
        {visible.length > limit && (
          <button
            type="button"
            className={styles.turnPage}
            onClick={() => {
              setLimit((previous) => previous + PAGE_SIZE);
            }}
          >
            {t('notebook.turnPage')}
          </button>
        )}
      </div>

      {notebook && pane === undefined && (
        <div className={styles.fabStrip}>
          <div className={styles.fabColumn}>
            {/* Adding one word by hand now lives beside the tab bar, where
                it is reachable from every screen rather than only this one.
                What stays here is the other way in: a text to pick words
                out of, which is an errand that only makes sense on the
                notebook it fills. */}
            <button
              type="button"
              className={styles.fabSmall}
              aria-label={t('notebook.paste')}
              onClick={() => {
                setPasteOpen(true);
              }}
            >
              <Icon name="note" size={20} weight={1.9} />
            </button>
          </div>
        </div>
      )}

      {viewOpen && (
        <ViewSheet
          order={order}
          onOrder={setOrder}
          levels={data.levels}
          level={level}
          onLevel={(next) => {
            narrow('level', next);
          }}
          kinds={data.kinds}
          kind={kind}
          onKind={(next) => {
            narrow('kind', next);
          }}
          onClose={() => {
            setViewOpen(false);
          }}
        />
      )}

      {pasteOpen && data.notebook && (
        <PasteSheet
          notebookId={data.notebook.id}
          targetLang={targetLang}
          onClose={() => {
            setPasteOpen(false);
          }}
        />
      )}

      {addOpen && data.notebook && (
        <AddSheet
          notebookId={data.notebook.id}
          targetLang={targetLang}
          meaningLang={meaningLang}
          onClose={() => {
            setAddOpen(false);
          }}
        />
      )}
    </Root>
  );
}
