/**
 * Pulling the words out of a text somebody pasted.
 *
 * This chooses nothing. It finds every distinct word in the text, sets
 * aside the ones the notebook already has, and hands the rest back in the
 * order they were read — the learner taps the ones they did not know. No
 * frequency list, no stop words, no guess about what is worth learning:
 * that judgement is theirs, and a list of "useful words" is exactly the
 * thing Lexpad does not do.
 *
 * It is written for any script, and that takes two rules rather than one.
 * In a language that puts spaces between its words, a word is a run of
 * letters, which keeps "well-known" and "don't" whole. In Chinese,
 * Japanese, Thai, Lao, Khmer and Burmese there are no spaces to run
 * between, so a run of letters is the whole sentence: a pasted Chinese
 * paragraph offered 很多人以为坚持是一种天赋 as one "word", which is not a
 * word and is not something anybody can put on a card. Those scripts are
 * segmented by `Intl.Segmenter`, which carries the dictionaries the job
 * needs.
 *
 * The text is walked a sentence at a time rather than as one blob only so
 * that a word is found once per reading order; nothing of the sentence is
 * kept. An example illustrates a meaning, and a word picked out of a paste
 * has none yet, so there is nowhere honest to put it.
 */
import { normalizeHeadword } from '@lexpad/core';

export interface Candidate {
  /** The word as it was written, which is what goes in the notebook. */
  word: string;
}

export interface Picked {
  candidates: Candidate[];
  /** How many distinct words the text had that are already in the notebook. */
  alreadyHave: number;
  /** True when the text held more new words than one screen should offer. */
  truncated: boolean;
  /**
   * True when the text is Chinese or Japanese and this engine could only
   * break it into single characters. The candidates are still real — a
   * character is a unit somebody can learn — but they are not the words of
   * the text, and the screen says so rather than letting them pass as words.
   */
  byCharacter: boolean;
}

/**
 * The most words one paste offers when nobody has said otherwise. Beyond
 * this the screen stops being a choice and becomes a wall, and nobody reads
 * to the end of it; the text can be pasted in pieces.
 *
 * It is a fallback rather than the rule: the real number comes from the
 * server, so it can be changed without three app releases.
 */
export const MAX_CANDIDATES = 300;

/** Runs of letters, apostrophes and hyphens: a word in a script with spaces. */
const WORD = /[\p{L}\p{M}][\p{L}\p{M}'’-]*/gu;

/** Sentence ends, including the ones used outside Latin scripts. */
const SENTENCE_END = /(?<=[.!?…。！？؟])\s+|\n+/u;

/**
 * The scripts that do not put spaces between words, and the locale whose
 * dictionary segments each one. Order matters: Japanese is written in Han
 * as well as kana, so kana is looked for first and a text with any in it is
 * Japanese; Han on its own is Chinese.
 *
 * Only the six that Lexpad offers are here. A language added to the
 * contract that writes without spaces is added here in the same change, or
 * its readers get sentences where they asked for words.
 */
const UNSPACED: readonly (readonly [RegExp, string])[] = [
  [/[\p{Script=Hiragana}\p{Script=Katakana}]/u, 'ja'],
  [/\p{Script=Han}/u, 'zh'],
  [/\p{Script=Thai}/u, 'th'],
  [/\p{Script=Lao}/u, 'lo'],
  [/\p{Script=Khmer}/u, 'km'],
  [/\p{Script=Myanmar}/u, 'my'],
];

/** The locale to segment this text with, or undefined if spaces will do. */
function unspacedLocale(text: string): string | undefined {
  return UNSPACED.find(([script]) => script.test(text))?.[1];
}

/**
 * A two-character Chinese word, used to ask the engine whether it has the
 * dictionary that Chinese and Japanese need. It is a fixture for a
 * capability probe rather than content: nothing shows it to anybody.
 *
 * The answer is not the same everywhere. Apple's engine carries the CJK
 * dictionary, so 坚持 comes back whole; Chromium leaves it out of the ICU
 * data it ships on Android, so the same call returns 坚 and 持. Thai, Lao,
 * Khmer and Burmese have their dictionaries on both.
 */
const CJK_PROBE = '坚持';

let cjkDictionary: boolean | undefined;

/** Whether this engine can break Chinese and Japanese into words. */
function hasCjkDictionary(): boolean {
  cjkDictionary ??=
    typeof Intl.Segmenter === 'function' &&
    [...new Intl.Segmenter('zh', { granularity: 'word' }).segment(CJK_PROBE)].filter(
      (part) => part.isWordLike === true,
    ).length === 1;
  return cjkDictionary;
}

/** Test seam: forgets the probe so a test can answer it differently. */
export function forgetEngineSupport(): void {
  cjkDictionary = undefined;
}

/**
 * The words of one sentence, in reading order.
 *
 * A segmented script keeps single characters, because 人 and น้ำ are whole
 * words; a spaced one keeps the two-letter minimum, which is what stops a
 * stray initial becoming a card. `isWordLike` is what leaves the
 * punctuation and the spacing behind.
 */
function wordsOf(sentence: string): { words: string[]; shortest: number; byCharacter: boolean } {
  const locale = unspacedLocale(sentence);
  if (locale === undefined || typeof Intl.Segmenter !== 'function') {
    return {
      words: [...sentence.matchAll(WORD)].map((match) => match[0]),
      shortest: 2,
      byCharacter: false,
    };
  }
  const segments = new Intl.Segmenter(locale, { granularity: 'word' }).segment(sentence);
  return {
    words: [...segments].filter((part) => part.isWordLike === true).map((part) => part.segment),
    shortest: 1,
    byCharacter: (locale === 'zh' || locale === 'ja') && !hasCjkDictionary(),
  };
}

/**
 * Finds the words worth offering. `known` holds normalised headwords the
 * notebook already has, so a word somebody wrote down last week is counted
 * rather than offered again.
 */
export function wordsInText(text: string, known: ReadonlySet<string>, most: number = MAX_CANDIDATES): Picked {
  const candidates: Candidate[] = [];
  const seen = new Set<string>();
  const counted = new Set<string>();
  let truncated = false;
  let byCharacter = false;

  for (const raw of text.split(SENTENCE_END)) {
    const sentence = raw.replace(/\s+/g, ' ').trim();
    if (sentence === '') continue;
    const { words, shortest, byCharacter: rough } = wordsOf(sentence);
    if (rough) byCharacter = true;
    for (const found of words) {
      const word = found.replace(/^['’-]+|['’-]+$/g, '');
      if (word.length < shortest) continue;
      const key = normalizeHeadword(word);
      if (key === '') continue;
      if (known.has(key)) {
        counted.add(key);
        continue;
      }
      if (seen.has(key)) continue;
      seen.add(key);
      if (candidates.length >= most) {
        truncated = true;
        continue;
      }
      candidates.push({ word });
    }
  }

  return { candidates, alreadyHave: counted.size, truncated, byCharacter };
}
