/**
 * How much of the notebook's sticky header is on screen while the list
 * scrolls (tester feedback, 2026-10-02: at full size it takes a third of a
 * phone before the first word).
 *
 * - `full`: at the top of the page, everything.
 * - `hidden`: scrolling down through the list, none of it; the list gets the
 *   screen. The status-bar strip (`topScrim`) stays.
 * - `tools`: scrolling back up, the search, the filter chips and the Show
 *   switches come back first. The title and the notebook chip return only
 *   at the top, where they were left.
 *
 * The header moves by `transform` alone and never changes height. A sticky
 * header that shrinks moves the list under the reader's thumb, the browser
 * corrects the scroll position for it, and that correction reads as
 * scrolling up, which opens the header again: it bounces.
 *
 * The thresholds are the tab bar's, so the two get out of the way together.
 */
import { useCallback, useEffect, useRef, useState, type RefObject } from 'react';

export type HeaderFold = 'full' | 'tools' | 'hidden';

/** Scroll this far back up and the tools come straight back (as the tab bar). */
const SHOW_BY = 24;

export function useHeaderFold(
  header: RefObject<HTMLElement | null>,
  tools: RefObject<HTMLElement | null>,
): {
  fold: HeaderFold;
  offset: number;
  reveal: (event: React.FocusEvent) => void;
  settle: (fold: HeaderFold) => void;
} {
  const [fold, setFold] = useState<HeaderFold>('full');
  const [heights, setHeights] = useState({ header: 0, tools: 0 });
  // Where the last scroll event left the page, and the lowest point reached
  // since the reader last moved down. A finger moves a few pixels per
  // event, so "back up by SHOW_BY" is measured from there, not from the
  // previous event. Refs rather than locals so `settle` can move them.
  const last = useRef(0);
  const lowest = useRef(0);

  // The header changes height when a narrowing chip or the page tabs
  // appear, so the distances are measured, not assumed.
  useEffect(() => {
    const element = header.current;
    if (!element) return;
    const measure = (): void => {
      const top = tools.current?.offsetTop ?? 0;
      // The header's top padding is the status-bar inset plus --s8. The
      // tools stop --s2 under that inset, so the search has a little of the
      // header's ground above it rather than sitting against the strip.
      const css = getComputedStyle(element);
      const space = (name: string): number => parseFloat(css.getPropertyValue(name)) || 0;
      const inset = (parseFloat(css.paddingTop) || 0) - space('--s8');
      const keep = Math.max(0, inset) + space('--s2');
      setHeights({ header: element.offsetHeight, tools: Math.max(0, top - keep) });
    };
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => {
      observer.disconnect();
    };
  }, [header, tools]);

  useEffect(() => {
    last.current = window.scrollY;
    lowest.current = last.current;
    const onScroll = (): void => {
      const y = window.scrollY;
      if (y > last.current) lowest.current = y;
      const element = header.current;
      // Never move a header somebody is typing in. A tapped chip keeps
      // focus too, so only a text field counts.
      const active = document.activeElement;
      const typing = active instanceof HTMLInputElement && (element?.contains(active) ?? false);
      // Within the header's own height the page itself shows all of it.
      if (y <= (element?.offsetHeight ?? 0) || typing) setFold('full');
      else if (y > last.current) setFold('hidden');
      else if (y < lowest.current - SHOW_BY) setFold((now) => (now === 'hidden' ? 'tools' : now));
      last.current = y;
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', onScroll);
    };
  }, [header]);

  /*
   * The page was just put back where the reader left it (placeMemory.ts),
   * and the header with it. The jump there is not the reader scrolling
   * down, so the scroll event it raises must not fold the header away.
   */
  const settle = useCallback((next: HeaderFold): void => {
    last.current = window.scrollY;
    lowest.current = last.current;
    setFold(next);
  }, []);

  const offset = fold === 'hidden' ? heights.header : fold === 'tools' ? heights.tools : 0;
  return {
    fold,
    offset,
    // Keyboard focus landing in a header that is out of sight brings it
    // back, so nobody tabs into something they cannot see. A tap does not:
    // tapping a chip while the tools are showing must not drop the title
    // over the list.
    reveal: (event: React.FocusEvent) => {
      if (event.target instanceof HTMLElement && event.target.matches(':focus-visible')) setFold('full');
    },
    settle,
  };
}
