import { dayIndex, directionOf, ttsLocaleOf, type LanguageCode, type Word } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { Icon } from '@/components/ui/Icon.js';
import { BoxMeter } from '@/components/ui/BoxMeter.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { dayLabel } from '@/lib/format.js';
import { platform } from '@/lib/platform/index.js';
import { useCanSpeak } from '@/lib/useCanSpeak.js';
import styles from './WordRow.module.css';

interface WordRowProps {
  word: Word;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  /** Self-test mode: the meanings stay covered until the row is tapped. */
  hideMeaning: boolean;
  revealed: boolean;
  /**
   * Compact leaves out the examples and collocations. It keeps every meaning:
   * a word saved for its second sense must not lose that sense just because
   * the examples are hidden.
   */
  compact: boolean;
  today: number;
  timeZone: string;
  /**
   * Which notebook the word came from. Set only when every notebook is in
   * view, where a page of mixed languages is unreadable without it.
   */
  from?: string;
  /** The word open beside the list, on a window wide enough for both. */
  selected?: boolean;
  onOpen: () => void;
  onReveal: () => void;
  onStar: (starred: boolean) => void;
  onGrade: (correct: boolean) => void;
}

/** How many senses a row shows, and how many collocations a full row shows. */
const ROW_SENSES = 3;
const FULL_COLLOCATIONS = 3;

/**
 * One ruled line of the notebook: the page it was written on and a dot in
 * its box colour in the gutter, the headword with its pronunciation and part
 * of speech, then the meanings, examples, collocations, correction and the
 * learner's note — or, in self-test mode, "Tap to reveal" and the two grades.
 */
export function WordRow({
  word,
  targetLang,
  meaningLang,
  hideMeaning,
  revealed,
  compact,
  today,
  timeZone,
  from,
  selected = false,
  onOpen,
  onReveal,
  onStar,
  onGrade,
}: WordRowProps): React.JSX.Element {
  const canSpeak = useCanSpeak(targetLang);
  const progress = word.progress;
  const starred = progress?.starred === true;
  const covered = hideMeaning && !revealed;
  const senses = (word.meanings ?? []).slice(0, ROW_SENSES);
  const collocations = compact ? [] : (word.collocations ?? []).slice(0, FULL_COLLOCATIONS);
  const memo = progress?.memo ?? '';
  const page = dayLabel(dayIndex(new Date(word.createdAt), timeZone), today).replace(
    t('notebook.yesterday'),
    t('notebook.yesterdayShort'),
  );

  return (
    <div
      className={cx(styles.row, covered && styles.rowCovered, selected && styles.rowSelected)}
      // Lets the notebook put a returning reader back at this row.
      data-word-id={word.id}
      onClick={covered ? onReveal : undefined}
      role={covered ? 'button' : undefined}
      tabIndex={covered ? 0 : undefined}
      aria-label={covered ? t('notebook.tapToReveal') : undefined}
      onKeyDown={
        covered
          ? (event) => {
              if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                onReveal();
              }
            }
          : undefined
      }
    >
      <div className={styles.body}>
        <div className={styles.head}>
          <div className={styles.headText}>
            <button
              type="button"
              className={styles.headword}
              aria-current={selected ? 'true' : undefined}
              onClick={(event) => {
                event.stopPropagation();
                onOpen();
              }}
            >
              <Bilingual lang={targetLang}>{word.headword}</Bilingual>
            </button>
            {((word.pronunciation ?? '') !== '' || (word.pos ?? '') !== '') && (
              <div className={styles.meta}>
                {(word.pronunciation ?? '') !== '' && (
                  <span className={styles.pron}>{word.pronunciation}</span>
                )}
                {(word.pos ?? '') !== '' && <span className={styles.pos}>{word.pos}</span>}
              </div>
            )}
          </div>
          <button
            type="button"
            className={cx(styles.action, starred && styles.starOn)}
            aria-label={starred ? t('action.unstar') : t('action.star')}
            aria-pressed={starred}
            onClick={(event) => {
              event.stopPropagation();
              onStar(!starred);
            }}
          >
            <Icon name={starred ? 'starOn' : 'star'} size={18} />
          </button>
          {canSpeak && (
            <button
              type="button"
              className={cx(styles.action, styles.speak)}
              aria-label={t('action.speak')}
              onClick={(event) => {
                event.stopPropagation();
                platform.tts.speak(word.headword, ttsLocaleOf(targetLang));
              }}
            >
              <Icon name="speaker" size={18} weight={1.9} />
            </button>
          )}
        </div>

        {!covered && (
          <div className={styles.senses}>
            {senses.map((sense, index) => {
              const example = compact ? undefined : sense.examples?.[0];
              return (
                <div key={`${sense.meaning}-${String(index)}`} className={styles.sense}>
                  <div className={styles.meaning} dir={directionOf(meaningLang)}>
                    {senses.length > 1 && <span className={styles.senseNumber}>{index + 1}.</span>}
                    <Bilingual lang={meaningLang}>{sense.meaning}</Bilingual>
                  </div>
                  {example !== undefined && (
                    <>
                      <div className={styles.example}>
                        <Bilingual lang={targetLang}>{example.sentence}</Bilingual>
                      </div>
                      {example.translation !== undefined && (
                        <div className={styles.exampleTranslation}>
                          <Bilingual lang={meaningLang}>{example.translation}</Bilingual>
                        </div>
                      )}
                    </>
                  )}
                </div>
              );
            })}
            {collocations.length > 0 && <div className={styles.collocations}>{collocations.join(' · ')}</div>}
            {(word.correction ?? '') !== '' && (
              <div className={styles.correction} dir={directionOf(meaningLang)}>
                <span className={styles.correctionOld}>
                  <Bilingual lang={meaningLang}>{word.originalMeaning ?? ''}</Bilingual>
                </span>{' '}
                {t('notebook.corrected')}
              </div>
            )}
          </div>
        )}

        {memo !== '' && (
          <div className={styles.memo} dir="auto">
            <Icon name="note" size={14} weight={2} className={styles.memoIcon} />
            <span>{memo}</span>
          </div>
        )}

        {/* What the left gutter used to carry: which box the word is in,
            when it was added, and where it came from. A column of its own
            cost every card sixteen points of width and pushed the word off
            the left edge; inline underneath, it reads as what it is --
            metadata about the row above it.

            The rung is drawn rather than named. Five shades of gold behind
            the words "Box 3" asked the reader to know there are five boxes
            and that higher is better before it told them anything; rising
            bars say both without being learnt. A word nobody has practised
            has no rung to draw, so it says so in words. */}
        <div className={styles.footer}>
          {progress === undefined ? (
            <span className={styles.box}>{t('notebook.notStarted')}</span>
          ) : (
            <BoxMeter box={progress.box} />
          )}
          <span className={styles.page}>{page}</span>
          {from !== undefined && (
            <span className={styles.from} dir="auto">
              {from}
            </span>
          )}
        </div>

        {progress?.retired === true && <div className={styles.retired}>{t('notebook.retired')}</div>}

        {covered && <div className={styles.revealHint}>{t('notebook.tapToReveal')}</div>}

        {hideMeaning && revealed && (
          <div className={styles.grade}>
            <button
              type="button"
              className={cx(styles.gradeButton, styles.gradeWrong)}
              onClick={(event) => {
                event.stopPropagation();
                onGrade(false);
              }}
            >
              {t('session.didntKnow')}
            </button>
            <button
              type="button"
              className={cx(styles.gradeButton, styles.gradeRight)}
              onClick={(event) => {
                event.stopPropagation();
                onGrade(true);
              }}
            >
              {t('session.knewIt')}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
