/** What the notebook screen reads, and how its controls narrow it. */
import {
  dayIndex,
  dayIso,
  groupByDay,
  selectWords,
  type Filter,
  type LanguageCode,
  type Order,
  type Word,
  kindCounts,
  levelsPresent,
  matchesKind,
  type Kind,
} from '@lexpad/core';
import { inView, listWords } from '@/db/repo.js';
import { localTimeZone } from '@/lib/format.js';

/** How the notebook is currently being viewed. */
export interface NotebookView {
  filter: Filter;
  order: Order;
  query: string;
  /** Narrows to one topic, from the Today screen. */
  topic?: string | undefined;
  /** Narrows to one CEFR band, from the Today screen. */
  level?: string | undefined;
  /** Narrows to one kind (phrasal verbs, idioms, nouns…). */
  kind?: Kind | undefined;
}

/** One notebook's languages, for rendering a word that belongs to it. */
export interface NotebookLangs {
  title: string;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
}

export interface NotebookData {
  /**
   * The notebook the page is anchored to: the one a new word is written
   * into and the one the search placeholder names. With every notebook in
   * view it is still one of them, because adding a word needs somewhere to
   * put it and the language of what is typed decides the rest.
   */
  notebook: { id: string; title: string; targetLang: LanguageCode; meaningLang: LanguageCode } | undefined;
  /** Every notebook in view, by id, so a row can carry its own languages. */
  byNotebook: Record<string, NotebookLangs>;
  /** Whether all notebooks are in view rather than one. */
  across: boolean;
  /** The words that match, already ordered. */
  words: Word[];
  /** Grouped into pages by the day they were added, for the Pages order. */
  pages: { day: string; words: Word[] }[];
  /** How many words the notebook holds in total, before filtering. */
  total: number;
  /** The CEFR bands and kinds present in the whole notebook, for the chips. */
  levels: string[];
  kinds: Kind[];
  today: number;
  todayIso: string;
}

export const EMPTY_NOTEBOOK: NotebookData = {
  notebook: undefined,
  byNotebook: {},
  across: false,
  words: [],
  pages: [],
  total: 0,
  levels: [],
  kinds: [],
  today: 0,
  todayIso: '',
};

/** Reads and narrows the notebook, entirely from local data. */
export async function loadNotebook(view: NotebookView, now: Date = new Date()): Promise<NotebookData> {
  const { notebooks, showing, all: everything } = await inView();
  const notebook = showing;
  if (!notebook) return EMPTY_NOTEBOOK;

  const timeZone = localTimeZone();
  const today = dayIndex(now, timeZone);
  const lists = await Promise.all(notebooks.map((one) => listWords(one.id)));
  const all = lists.flat();

  let selected = selectWords(all, {
    filter: view.filter,
    order: view.order,
    query: view.query,
    today,
  });
  if (view.topic !== undefined) selected = selected.filter((word) => word.category === view.topic);
  if (view.level !== undefined) selected = selected.filter((word) => word.level === view.level);
  const kind = view.kind;
  if (kind !== undefined) selected = selected.filter((word) => matchesKind(word, kind));

  return {
    notebook: {
      id: notebook.id,
      title: notebook.title,
      targetLang: notebook.targetLang,
      meaningLang: notebook.meaningLang,
    },
    // With every notebook in view a row cannot take its direction, its font
    // or its voice from one of them, so each word carries its own.
    byNotebook: Object.fromEntries(
      notebooks.map((one) => [
        one.id,
        { title: one.title, targetLang: one.targetLang, meaningLang: one.meaningLang },
      ]),
    ),
    across: everything,
    words: selected,
    pages: groupByDay(selected, timeZone),
    total: all.length,
    levels: levelsPresent(all),
    kinds: kindCounts(all).map((entry) => entry.kind),
    today,
    todayIso: dayIso(now, timeZone),
  };
}
