import { useEffect, useState } from 'react';

/**
 * The value, settled. It follows `value` only once typing has paused for
 * `delay`, so a search box asks the server about what someone meant rather
 * than about every letter on the way there.
 */
export function useDebounced<T>(value: T, delay = 300): T {
  const [settled, setSettled] = useState(value);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      setSettled(value);
    }, delay);
    return () => {
      window.clearTimeout(timer);
    };
  }, [value, delay]);

  return settled;
}
