import { KINDS, type Kind } from '@lexpad/core';
import { getMeta, setMeta } from '@/db/schema.js';
import { FILTERS, type Filter, type Order } from './filters.js';

/**
 * How the notebook was last looked at on this device: the chip, the order,
 * the level and kind narrowings, and the two display switches.
 *
 * Testers lost it every time they visited another tab, because it lived in
 * the screen's own state and the screen unmounts (2026-10-02). It is kept in
 * memory, so coming back is instant and shows no flash of the defaults, and
 * in IndexedDB, so it survives a restart. It is a device preference, not an
 * account one, and is never synced. A search is not kept: it is a question
 * asked once, not a way of reading the notebook.
 */
export interface RememberedView {
  filter: Filter;
  order: Order;
  showMeanings: boolean;
  showExamples: boolean;
  level?: string;
  kind?: Kind;
}

export const DEFAULT_VIEW: RememberedView = {
  filter: 'all',
  order: 'recent',
  showMeanings: true,
  showExamples: true,
};

let remembered: RememberedView | undefined;

/** The view held in memory, if this session has one yet. */
export function rememberedView(): RememberedView | undefined {
  return remembered;
}

/** Reads the stored view once, falling back to the defaults; drops values a newer build no longer knows. */
export async function loadView(): Promise<RememberedView> {
  if (remembered !== undefined) return remembered;
  const stored = await getMeta('notebookView');
  const view: RememberedView = { ...DEFAULT_VIEW };
  if (stored !== null) {
    if ((FILTERS as readonly string[]).includes(stored.filter)) view.filter = stored.filter as Filter;
    if (stored.order === 'recent' || stored.order === 'position' || stored.order === 'alpha')
      view.order = stored.order;
    view.showMeanings = stored.showMeanings !== false;
    view.showExamples = stored.showExamples !== false;
    if (typeof stored.level === 'string') view.level = stored.level;
    if (stored.kind !== undefined && (KINDS as readonly string[]).includes(stored.kind))
      view.kind = stored.kind as Kind;
  }
  remembered = view;
  return view;
}

/** Keeps the view for the next visit, in memory at once and on disk after. */
export function saveView(view: RememberedView): void {
  remembered = view;
  void setMeta('notebookView', view).catch(() => undefined);
}

/** For tests: forget what this session remembered. */
export function forgetView(): void {
  remembered = undefined;
}
